/**
 * NeighbourAssist referral engine (student prototype, not an eligibility assessor).
 * No resident personal data, NRIC, CPF balance, documents, or medical detail is requested.
 * Major referral sources reviewed on 17–19 October 2026; current agency instructions take precedence.
 */
export type Category = 'financial'|'housing'|'cpf'|'health'|'municipal'|'fines'|'employment'|'family'|'unsure';
export type Answers = Record<string,string>;
export type Question = {id:string; title:string; hint?:string; options:{value:string;label:string}[]};
export type Service = {id:string;name:string;agency:string;description:string;url:string;phone?:string;phoneHours?:string;offline?:string;steps:string[];checklist:string[];caution:string;};
const opt=(...entries:[string,string][])=>entries.map(([value,label])=>({value,label}));

export const categories:{id:Category;label:string;summary:string;symbol:string}[]=[
{id:'financial',label:'Everyday expenses',summary:'Food, bills, income and financial assistance',symbol:'$'},
{id:'housing',label:'Housing & rental',summary:'Public rental flats, housing costs and rightsizing',symbol:'⌂'},
{id:'cpf',label:'CPF & retirement',summary:'Understand CPF withdrawal or senior support options',symbol:'◎'},
{id:'health',label:'Medical costs',summary:'Subsidies, clinic visits and hospital bills',symbol:'+'},
{id:'municipal',label:'Neighbourhood issues',summary:'Lifts, public-area repairs, cleanliness',symbol:'▦'},
{id:'fines',label:'Fines & appeals',summary:'Parking, traffic and active-mobility penalties',symbol:'!'},
{id:'employment',label:'Work & employment',summary:'Unpaid salary, dismissal and workplace concerns',symbol:'▤'},
{id:'family',label:'Family & social support',summary:'Family relationships, caregiving and childcare',symbol:'♡'},
{id:'unsure',label:'Not sure',summary:'Help me find where to start',symbol:'?'},
];

